import {createStudy,clamp} from './core.js';
const study=createStudy({id:9,title:'Elastic Editorial',category:'Typography / Scroll',accent:'#e2ff00',background:'#0e100d',foreground:'#f0efdf'});
const runway=document.querySelector('#editorial-runway'),stage=document.querySelector('#editorial-stage'),orbit=document.querySelector('#editorial-orbit');
const rows=['read','between','the','lines'].map(name=>document.querySelector('#row-'+name));
const chapterTitles=['01 / ARRIVAL','02 / DISPLACEMENT','03 / INTERFERENCE','04 / RESOLUTION'];
const chapterCopy=['A page isn’t a place.\nIt’s a sequence.','Position changes\nthe conversation.','Background becomes\nforeground.','Still the same words.\nA different understanding.'];
let start=0,length=1,visualProgress=0,dirty=true,last=-1;
function measure(){start=window.scrollY+runway.getBoundingClientRect().top-72;length=Math.max(1,runway.offsetHeight-stage.offsetHeight);dirty=true}
function render(){const actual=clamp((window.scrollY-start)/length,0,1);document.querySelector('#editorial-location').textContent='LOCATION / '+(actual*100).toFixed(1)+'%';document.querySelector('#editorial-progress').style.width=actual*100+'%';if(study.running())visualProgress=actual;const p=visualProgress;if(!dirty&&Math.abs(p-last)<.0001)return;last=p;dirty=false;const w=stage.clientWidth;rows[0].style.transform=`translate(${(-p*w*.42).toFixed(1)}px,${(-p*45).toFixed(1)}px) rotate(${-p*7}deg)`;rows[1].style.transform=`translate(${(-Math.sin(p*Math.PI)*w*.25).toFixed(1)}px,0) scale(${1+p*.3})`;rows[2].style.transform=`translate(${(Math.sin(p*Math.PI*1.2)*w*.24).toFixed(1)}px,${p*15}px) rotate(${p*8}deg)`;rows[3].style.transform=`translate(${(-p*w*.32).toFixed(1)}px,0) scale(${1+p*.32})`;rows[0].style.opacity=String(1-p*.68);rows[2].style.opacity=String(.62+Math.sin(p*Math.PI)*.38);orbit.style.transform=`translate(${(-p*w*.4).toFixed(1)}px,${(Math.sin(p*Math.PI)*70).toFixed(1)}px) rotate(${-20+p*180}deg) scale(${.8+p*.7})`;orbit.classList.toggle('is-forward',p>.52);const chapter=Math.min(3,Math.floor(actual*4));document.querySelector('#editorial-chapter').textContent=chapterTitles[chapter];document.querySelector('#editorial-copy').textContent=chapterCopy[chapter];document.querySelectorAll('[data-chapter]').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===chapter)));stage.dataset.chapter=chapter}
function update(){dirty=true;study.invalidate()}
window.addEventListener('scroll',update,{passive:true});study.cleanup(()=>window.removeEventListener('scroll',update));study.onResize(()=>{measure();study.invalidate()});study.onFrame(render);study.onMotion(running=>{if(running)measure();dirty=true;render()});
document.querySelectorAll('[data-chapter]').forEach(button=>button.addEventListener('click',()=>{const p=(Number(button.dataset.chapter)+.12)/4;window.scrollTo({top:start+length*p,behavior:study.running()?'smooth':'instant'})}));document.querySelector('#editorial-return').addEventListener('click',()=>window.scrollTo({top:0,behavior:study.running()?'smooth':'instant'}));study.setReset(()=>{visualProgress=0;last=-1;window.scrollTo({top:0,behavior:'instant'});dirty=true;study.invalidate()});measure();render();
